            if options.len() == 1 {
                return Action::CastSpell { object_id: spell.object_id, targets: vec![options[0].clone()], sacrifice: None, exile_count: None, alternative_cost: None };
            }
            let target = self.prompt_target_selection(view, &spell.name, options);
